  double m=s/r, sd=sqrt(ss/r-m*m);
  printf("%ld elem %ld: mean %.4f std %.4f min %.3f max %.3f\n",n*W,r,m,sd,mn,mx);
  n++;
 }
 double m=gs/cnt; printf("TOTAL %ld mean %.4f std %.4f\n",cnt,m,sqrt(gss/cnt-m*m));
}
EOF
